    let (mut lo, mut hi) = (0, a.len() - 1);
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < a[mid + 1] {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo // Adjacent values differ; outside endpoints are negative infinity.
}

