#[derive(Clone, Debug, PartialEq)]
struct RandomNode {
    value: i32,
    next: Option<usize>,
    random: Option<usize>,
}
fn deep_copy(arena: &[RandomNode]) -> Vec<RandomNode> {
    // Index edges refer within this arena. Cloning all records allocates a
    // separate arena; identical indexes now refer to the copied nodes.
    arena.to_vec()
}
fn copied_pairs(values: &[i32], random: &[Option<usize>]) -> String {
    let original: Vec<_> = values
        .iter()
        .enumerate()
        .map(|(i, &value)| RandomNode {
            value,
            next: (i + 1 < values.len()).then_some(i + 1),
            random: random[i],
        })
        .collect();
    let mut copy = deep_copy(&original);
    assert_eq!(original, copy);
    let out = copy
        .iter()
        .map(|n| {
            format!(
                "{}:{}",
                n.value,
                n.random.map_or("null".into(), |i| i.to_string())
            )
