        match root {
            None => out.push("#".into()),
            Some(n) => {
                out.push(n.value.to_string());
                visit(&n.left, out);
                visit(&n.right, out);
            }
        }
    }
    let mut out = Vec::new();
    visit(root, &mut out);
    out.join(",")
}

