fn closest(points: &[(i32, i32)], k: usize) -> Vec<(i32, i32)> {
    let mut heap = std::collections::BinaryHeap::new();
    for &(x, y) in points {
        let distance = i64::from(x) * i64::from(x) + i64::from(y) * i64::from(y);
        heap.push((distance, x, y));
        if heap.len() > k {
            heap.pop();
