    let mut arrivals = jobs.to_vec();
    arrivals.sort_by_key(|&(id, t, _)| (t, id));
    let mut ready = std::collections::BinaryHeap::new();
    let (mut i, mut time) = (0, 0);
    let mut out = Vec::new();
    while i < arrivals.len() || !ready.is_empty() {
