fn word_exists(grid: &[Vec<u8>], word: &[u8]) -> bool {
    fn search(
        g: &[Vec<u8>],
        w: &[u8],
        r: usize,
        c: usize,
        i: usize,
        seen: &mut [Vec<bool>],
    ) -> bool {
        if seen[r][c] || g[r][c] != w[i] {
            return false;
        }
        if i + 1 == w.len() {
            return true;
        }
        seen[r][c] = true;
        let mut found = false;
        for (dr, dc) in [(-1, 0), (1, 0), (0, -1), (0, 1)] {
            let (a, b) = (r as isize + dr, c as isize + dc);
            if a >= 0
