fn solve_sudoku(grid: &mut [[u8; 9]; 9]) -> bool {
    let empty = (0..9)
        .flat_map(|r| (0..9).map(move |c| (r, c)))
        .find(|&(r, c)| grid[r][c] == 0);
    let Some((r, c)) = empty else {
        return true;
    };
    for value in 1..=9 {
        let row = (0..9).all(|i| grid[r][i] != value);
        let col = (0..9).all(|i| grid[i][c] != value);
        let block = (r / 3 * 3..r / 3 * 3 + 3)
            .all(|a| (c / 3 * 3..c / 3 * 3 + 3).all(|b| grid[a][b] != value));
        if row && col && block {
            grid[r][c] = value;
            if solve_sudoku(grid) {
                return true;
            }
            grid[r][c] = 0;
        }
    }
    false
}

